def word_frequency(text: str) -> dict[str, int]:
    import string
    freq = {}
    for w in text.split():
        cleaned = w.strip(string.punctuation)
        if cleaned:
            freq[cleaned.lower()] = freq.get(cleaned, 0) + 1
    return freq
